from marimo._ai._tools.base import ToolContext
from marimo._ai._tools.tools.dependency_graph import (
    GetCellDependencyGraph, GetCellDependencyGraphArgs, VariableInfo,
)
from marimo._ai._tools.utils.exceptions import ToolExecutionError

app = App()

@app.cell
def a():
    x = 1
    def foo():
        return x
    return x, foo

@app.cell
def b(x):
    y = x + 1
    return (y,)

@app.cell
def c(y):
    z = y + 1
    return (z,)

iapp = InternalApp(app)
graph = iapp.graph
cm = iapp.cell_manager
ids = [cd.cell_id for cd in cm.cell_data()]
print('ids', ids)

class FM:
    app = iapp
class Sess:
    app_file_manager = FM()

tool = GetCellDependencyGraph(ToolContext())
tool.context.get_session = lambda sid: Sess()

out = tool.handle(GetCellDependencyGraphArgs(session_id='s'))
print('status', out.status)
print('order match', [c.cell_id for c in out.cells] == ids)
for c in out.cells:
    print(c.cell_id, repr(c.cell_name), 'defs', [(v.name,v.kind) for v in c.defs], 'refs', c.refs, 'p', c.parent_cell_ids, 'ch', c.child_cell_ids)
print('variable_owners', out.variable_owners)
print('multiply_defined', out.multiply_defined)
print('cycles', out.cycles)

mid = ids[1]
out2 = tool.handle(GetCellDependencyGraphArgs(session_id='s', cell_id=mid, depth=1))
print('depth1 from mid', sorted([c.cell_id for c in out2.cells]), '== all 3?', sorted([c.cell_id for c in out2.cells])==sorted(ids))

out3 = tool.handle(GetCellDependencyGraphArgs(session_id='s', cell_id=ids[0], depth=None))
print('closure from a', sorted([c.cell_id for c in out3.cells])==sorted(ids))

out4 = tool.handle(GetCellDependencyGraphArgs(session_id='s', cell_id=ids[0], depth=1))
print('depth1 from a', sorted([c.cell_id for c in out4.cells]), 'expect a,b')

try:
    tool.handle(GetCellDependencyGraphArgs(session_id='s', cell_id='nonexistent'))
    print('NO ERROR - BAD')
except ToolExecutionError as e:
    print('CELL_NOT_FOUND code:', e.code)

print('VarInfo eq', VariableInfo('a','variable')==VariableInfo('a','variable'))
