from marimo._ast.compiler import compile_cell
from marimo._ai._tools.base import ToolContext
from marimo._ai._tools.tools.dependency_graph import (
    GetCellDependencyGraph, GetCellDependencyGraphArgs,
)

# Build a graph with a multiply-defined var and a cycle.
graph = DirectedGraph()
codes = {
    "c1": "x = 1",
    "c2": "x = 2",       # multiply-defined x
    "c3": "a = b",       # cycle a<->b
    "c4": "b = a",
}
names = {"c1": "one", "c2": "two", "c3": "three", "c4": "four"}
for cid, code in codes.items():
    impl = compile_cell(code, cell_id=cid)
    graph.register_cell(cid, impl)

class CM:
    def cell_data(self):
        class CD:
            def __init__(self, cid): self.cell_id = cid
        return [CD(c) for c in codes]
    def cell_name(self, cid): return names[cid]

class IApp:
    graph = graph
    cell_manager = CM()
class FM:
    app = IApp()
class Sess:
    app_file_manager = FM()

tool = GetCellDependencyGraph(ToolContext())
tool.context.get_session = lambda sid: Sess()
out = tool.handle(GetCellDependencyGraphArgs(session_id='s'))
print('multiply_defined', out.multiply_defined)
print('variable_owners', out.variable_owners)
print('cycles', out.cycles)
print('cells order', [c.cell_id for c in out.cells])
for c in out.cells:
    print(c.cell_id, c.cell_name, [(v.name, v.kind) for v in c.defs], c.refs, c.parent_cell_ids, c.child_cell_ids)
